<?php
require_once __DIR__.'/http.php';require_once __DIR__.'/money.php';
function mc_clean_cep($v): string { return substr(preg_replace('/\D/','',(string)$v),0,8); }
function mc_env_num(string $n,float $fallback): float { $v=(float)getenv($n);return $v>0?$v:$fallback; }
function mc_demo_quote(): array { return [['id'=>'demo-economico','name'=>'Frete econômico (DEMO)','priceCents'=>1290,'deliveryDays'=>8,'company'=>'Demo','service'=>'Econômico'],['id'=>'demo-expresso','name'=>'Frete expresso (DEMO)','priceCents'=>2190,'deliveryDays'=>4,'company'=>'Demo','service'=>'Expresso']]; }
function mc_shipping_quote(array $cart,string $destCep): array { if(strtolower((string)(getenv('SHIPPING_MODE')?:'demo'))!=='melhorenvio')return mc_demo_quote();$token=(string)getenv('MELHOR_ENVIO_TOKEN');if(!$token)throw new RuntimeException('MELHOR_ENVIO_TOKEN não configurado.');$from=mc_clean_cep(getenv('SHIPPING_ORIGIN_CEP'));$to=mc_clean_cep($destCep);if(strlen($from)!==8||strlen($to)!==8)throw new RuntimeException('CEP de origem/destino inválido.');$sandbox=strtolower((string)(getenv('MELHOR_ENVIO_ENVIRONMENT')?:'sandbox'))!=='production';$root=$sandbox?'https://sandbox.melhorenvio.com.br':'https://melhorenvio.com.br';$products=[];$w=mc_env_num('SHIPPING_DEFAULT_WIDTH_CM',16);$h=mc_env_num('SHIPPING_DEFAULT_HEIGHT_CM',3);$l=mc_env_num('SHIPPING_DEFAULT_LENGTH_CM',20);$kg=mc_env_num('SHIPPING_DEFAULT_WEIGHT_KG',0.15);foreach($cart as $i)$products[]=['id'=>$i['id'],'width'=>$w,'height'=>$h,'length'=>$l,'weight'=>$kg,'insurance_value'=>mc_brl((int)$i['priceCents']),'quantity'=>(int)$i['quantity']];$body=['from'=>['postal_code'=>$from],'to'=>['postal_code'=>$to],'products'=>$products,'options'=>['receipt'=>false,'own_hand'=>false]];$services=trim((string)getenv('MELHOR_ENVIO_SERVICES'));if($services!=='')$body['services']=$services;$r=mc_http_json($root.'/api/v2/me/shipment/calculate','POST',['Authorization'=>'Bearer '.$token,'Accept'=>'application/json','Content-Type'=>'application/json','User-Agent'=>(string)(getenv('MELHOR_ENVIO_USER_AGENT')?:'Metal Color')],$body);if($r['status']<200||$r['status']>=300)throw new RuntimeException($r['data']['message']??('Melhor Envio HTTP '.$r['status']));$out=[];foreach($r['data'] as $x){if(!is_array($x)||isset($x['error'])||(!isset($x['custom_price'])&&!isset($x['price'])))continue;$out[]=['id'=>(string)$x['id'],'name'=>(($x['company']['name']??'Transportadora').' - '.($x['name']??'Serviço')),'priceCents'=>(int)round((float)($x['custom_price']??$x['price'])*100),'deliveryDays'=>(int)($x['custom_delivery_time']??$x['delivery_time']??0),'company'=>$x['company']['name']??'','service'=>$x['name']??''];}usort($out,fn($a,$b)=>$a['priceCents']<=>$b['priceCents']);return $out; }
